attributes.twig:
{# Last updated by Allison September 21, 2026 to correct for IIIF President 3.0 validation errors:
     - specifically: Allison changed the 'description' to process only the first value if iterable,
     set the computed rights statement to CC-NC-ND by default -- https://creativecommons.org/licenses/by-nc-nd/4.0/,
     moved the value for data.rights to the "requiredStatement" property,
     and removed the no-longer-valid 'within' property (see specs ChangeLog note here https://iiif.io/api/presentation/3.0/change-log/#1210-rename-within-to-partof)
Originally adapted by Allison in August 2026 to structure for IIIF Choice manifest recipes.
Original template version lasted updated 6/25/2026 by Allison to account for -excluding- documents with dr:for = "texts" from inclusion on the display.
This Template generates IIIF 3.0 Presentation API Manifest from a Strawberry Field  JSON.
Updated 22/04/2025 for 1.5.0 to match CWS Manifests
Updated 31/10/2023 for 1.3.0 
Changes: 
  - Better Labeling for Items 
  - Adds Rights
  - Fixes on Canvas IDs 
  - Deals with PDFs too, joining them all together 
  - Adds MarkDown support for Description 
  - Fixes Structures/Canvas IDs 
  - Adds Annotations for Images 
  - Adds PDF/Document/pages 
  - Adds Thumbnail for Video 
  - Fixes mirador_path to handle both standard and self-closing polygon tags. 
Structures passed from Archipelago are 
- node 
  The full Node entity 
- data 
  The Full JSON Structure converted in an Array 
- iiif_server 
  The publicly available IIIF Server (Global Setting)​ 
Since JSON was decoded into the 'data' values are valid PHP but could not 
be valid JSON when outputting. So We use data.description|json_encode|raw 
Without Double quotes. 
#} 
{%- set structureCanvasIds = [] %} 
{# with 150 being Cantaloupe's setup PDF rastering resolution and 72 what PDFINFO produces by default #} 
{%- set baseurl =  url('<front>')|render -%} 
{%- set Webserverurl =  baseurl -%} 
{%- set IIIFserverurl = iiif_server ? iiif_server ~ '/': Webserverurl -%} 
{%- set currenturl = url('<current>')|render -%} 
{%- set parentcollectionurl = '' -%} 
{%- set itemCount = 0 -%} 
{%- if node.id %} 
    {%- set nodeurl = url('entity.node.canonical', {'node': node.id}, {'absolute': true}) -%} 
{%- else -%} 
    {%- set nodeurl = currenturl -%} 
{%- endif -%} 
{%- if attribute(data, 'ismemberof') %} 
    {%- if attribute(data, 'ismemberof') is iterable -%} 
	    {%- for collection in attribute(data, 'ismemberof') -%} 
		   {%- set parentcollectionurl = url('entity.node.canonical', {'node': collection}, {'absolute': true}) -%} 
	    {%- endfor -%} 
	{%- else -%} 
		{%- set parentcollectionurl = url('entity.node.canonical', {'node': attribute(data, 'ismemberof')}, {'absolute': true}) -%} 
    {%- endif -%} 
{%- endif -%} 
{%- if attribute(data, 'ispartof') -%} 
    {%- if attribute(data, 'ispartof') is iterable -%} 
	{%- for child in attribute(data, 'ispartof') -%} 
		{%- set parentnodeurl = url('entity.node.canonical', {'node': child}, {'absolute': true}) -%} 
	{%- endfor -%} 
	{%- else -%} 
		{%- set parentnodeurl = url('entity.node.canonical', {'node': attribute(data, 'ispartof')}, {'absolute': true}) -%} 
   {%- endif -%} 
{%- endif -%} 
{%- set len = language.getId() ? language.getId() : "en" -%} 
{% set computed_rights = "http://creativecommons.org/licenses/by-nc-nd/4.0/" %} 
{%- set max_thumb_width = 240 -%}
{ 
  "@context": [ 
  "http://www.w3.org/ns/anno.jsonld", 
  "http://iiif.io/api/presentation/3/context.json" 
  ], 
  "type": "Manifest", 
  "id": "{{ currenturl }}", 
  "label": { 
    "{{ len }}": [ 
      {{ node.label|json_encode|raw }} 
    ] 
  }, 
  "rights": {{ computed_rights|json_encode|raw }},   
  
  "requiredStatement": { 
    "label": { "en": [ "Attribution" ] }, 
    "value": { "en": {{ data.rights|json_encode|raw }} }
  }, 
"metadata": [
{%-  for agent in attribute(data, 'creator_lod') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          {{- agent.role_label|json_encode|raw -}} 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- agent.name_label|json_encode|raw -}} 
        ] 
      } 
    }, 
{%-  endfor -%}
{%-  for agent in attribute(data, 'edm_agent') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          {{- agent.role_label|json_encode|raw -}} 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- agent.name_label|json_encode|raw -}} 
        ] 
      } 
    }, 
{%-  endfor -%}
{%- if attribute(data, 'term_aat_getty') is iterable -%}
  {%-  for term in attribute(data, 'term_aat_getty') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          "Genre" 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- term.label|json_encode|raw -}} 
        ] 
      } 
    }, 
  {%-  endfor -%}
{%- endif -%}
{%- if attribute(data, 'subject_lcgft_terms') is iterable -%}
  {%-  for term in attribute(data, 'subject_lcgft_terms') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          "Genre" 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- term.label|json_encode|raw -}} 
        ] 
      } 
    }, 
  {%-  endfor -%}
{% endif %}
{#- From facets subject_loc[*].label,subject_wikidata[*].label,subject_lcnaf_geographic_names[*].label, subject_temporal[*].label,pubmed_mesh[*].label -#}
{%- if attribute(data, 'subject_loc') is iterable -%}
  {%-  for subject in attribute(data, 'subject_loc') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          "Subject" 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- subject.label|json_encode|raw -}} 
        ] 
      } 
    }, 
  {%-  endfor -%}
{%- endif -%}
{%- if attribute(data, 'subject_wikidata') is iterable -%}
  {%-  for subject in attribute(data, 'subject_wikidata') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          "Subject" 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- subject.label|json_encode|raw -}} 
        ] 
      } 
    }, 
  {%-  endfor -%}
{%- endif -%}
{%- if attribute(data, 'subject_lcnaf_geographic_names') is iterable -%}
  {%-  for subject in attribute(data, 'subject_lcnaf_geographic_names') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          "Subject" 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- subject.label|json_encode|raw -}} 
        ] 
      } 
    }, 
  {%-  endfor -%}
{%- endif -%}
{%- if attribute(data, 'subject_temporal') is iterable -%}
  {%-  for subject in attribute(data, 'subject_temporal') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          "Subject" 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- subject.label|json_encode|raw -}} 
        ] 
      } 
    }, 
  {%-  endfor -%}
{%- endif -%}
{%- if attribute(data, 'pubmed_mesh') is iterable -%}
  {%-  for subject in attribute(data, 'pubmed_mesh') -%} 
    { 
      "label": { 
        "{{- len -}}": [ 
          "Subject" 
        ] 
      }, 
      "value": { 
        "{{- len -}}": [ 
          {{- subject.label|json_encode|raw -}} 
        ] 
      } 
    }, 
  {%-  endfor -%}
{%- endif -%}
{
"label": {
  "{{- len -}}": [ "Description"] },
  {% if data.description|length > 0 and data.description is iterable %}
  "value": {"{{- len -}}": [ {{- data.description[0]|json_encode|raw -}} ]}
  {% else %} 
   {% if data.description|length > 0 %}
     "value": {"{{- len -}}": [ {{- data.description[0]|json_encode|raw -}} ]}
   {% endif %}
  {% endif %}    
        },
        
{%- if data.note is not empty -%}
{
"label": {
"{{- len -}}": [
"Note"
]
},
"value": { 
"{{- len -}}": [ 
{{- data.note|json_encode|raw -}}
]
}
}, 
{%- endif -%}
{
"label": {
"{{ len }}": [
"navDate"
]
},
"value":  {
"{{ len }}": [
   "{{ node.getChangedTime|date("F jS \\a\\t g:ia") }}"
    ]
  }
},
{
"label": {
   "{{ len }}": [
       "license"
  ]
},
"value": {
  "{{ len }}": [
     {{ computed_rights|json_encode|raw }}
     ]
    }
  }
],
{% if attribute(data, 'ismemberof') -%}  
  "partOf": [ { "id": "{{ parentcollectionurl }}/metadata/iiifmanifest3collection/default.jsonld", "type": "Manifest" } ], 
{%- endif -%} 
{%- if attribute(data, 'ispartof') %} 
  "partOf": [ { "id": "{{ parentnodeurl }}/metadata/iiifmanifest3cws/default.jsonld", "type": "Manifest" } ], 
{%- endif -%} 

{#
{%- if node.uuid.value -%} 
    "service": [ 
        { 
            "id": "{{ baseurl }}iiifcontentsearch/v2/do/{{ node.uuid.value }}/metadatadisplayexposed/iiifmanifest/mode/advanced/page/0", 
            "type": "SearchService2" 
        }, 
        { 
            "id": "{{ baseurl }}iiifcontentsearch/v1/do/{{ node.uuid.value }}/metadatadisplayexposed/iiifmanifest/mode/advanced/page/0", 
            "type": "SearchService1", 
            "@context": "http://iiif.io/api/search/1/context.json", 
            "profile": "http://iiif.io/api/search/1/search" 
        }, 
        { 
            "@id": "{{ baseurl }}iiifcontentsearch/v1/do/{{ node.uuid.value }}/metadatadisplayexposed/iiifmanifest/mode/advanced/page/0", 
            "@context": "http://iiif.io/api/search/0/context.json", 
            "profile": "http://iiif.io/api/search/0/search" 
        } 
    ], 
{%- endif -%}
#}
"items": [
{#- ImagesManifest -#} 
{#- Count Images upfront -#} 
{%- if (attribute(data, 'as:image')|length > 0) -%} 
{%- if itemCount > 0 -%} 
, 
{%- endif -%} 
{%- endif -%} 
{% for page in attribute(data, 'as:image') %} 
   {%- set itemCount = itemCount + 1 %}
   {% set filename_label = page["name"] %} 
   {%- set cantaloupeid  = IIIFserverurl ~ page['url']|replace({'s3://':''})|replace({'private://':''})|url_encode -%} 
   {%- if page["flv:exif"] -%} 
      {%- set width = page["flv:exif"].ImageWidth -%} 
   {%- else  -%} 
      {%- set width = 1200 -%} 
  {%- endif -%} 
  {%- if page["flv:exif"] -%} 
    {%- set height = page["flv:exif"].ImageHeight -%} 
  {%- else  -%} 
    {%- set height = 1600 -%} 
  {%- endif -%} 
  {%- set thumb_width = width < max_thumb_width ? width: max_thumb_width -%} 
  {%- set thumb_height = (thumb_width/width * height)|round() -%} 
  {% set canvasId = nodeurl|render ~ '/iiif/canvas/p' ~ itemCount %} 
  {% set structureCanvasIds = structureCanvasIds|merge([canvasId]) %}
{% set thumbnail -%} 
"thumbnail": [ 
        { 
          "id": "{{ cantaloupeid }}/full/{{thumb_width}},/0/default.jpg", 
          "type": "Image", 
          "format": "image/jpeg", 
          "width": {{ thumb_width }}, 
          "height": {{ thumb_height }} 
        } 
      ], 
{%- endset %} 
   {% if itemCount == '1' %}
    {
      "id": "{{ canvasId }}", 
      "type": "Canvas", 
      "label": { "{{ len }}": [ 
       {{ data.label|json_encode|raw }} 
      ]}, 
      {{ thumbnail }} 
      "height": {{ height }}, 
      "width": {{ width }}, 
      "items": [ 
        { 
          "id": "{{ nodeurl }}/iiif/page/p{{ itemCount}}", 
          "type": "AnnotationPage", 
          "items": [ 
            { 
              "id": "{{ nodeurl }}/iiif/annotation/p{{ itemCount }}", 
              "type": "Annotation", 
              "motivation": "painting",           
              "body": {
                "type": "Choice",
                "items": [
     		   {
      			 "id": "{{ cantaloupeid }}/full/full/0/default.jpg", 
      		     "type": "Image", 
      		     "format": "image/jpeg",
      		     "height": {{ height }}, 
      		     "width": {{ width }},
      		     "label": {
        			 "en": [
          		   		"{{ filename_label }}"
        				]
      			  	}, 
      			  "service": [ 
       		   	{ 
         		  "id": "{{ cantaloupeid }}", 
         		 "type": "ImageService2", 
         		"profile": "level2" 
         		}
       	 	   ]
     	  	},
	 {% endif %}
		{% if itemCount != '1' %}
                  {
				   "id": "{{ cantaloupeid }}/full/full/0/default.jpg", 
                   "type": "Image", 
                   "format": "image/jpeg",
                   "height": {{ height }}, 
                   "width": {{ width }},
                   "label": {
                     "en": [
                       "{{ filename_label }}"
                     ]
                   }, 
                   "service": [ 
                    { 
                      "id": "{{ cantaloupeid }}", 
                      "type": "ImageService2", 
                      "profile": "level2" 
                      }
                    ]
                  }
		{{ not loop.last ? ',' : '' }}   
		{% endif %}		
{% endfor -%}
			]			
             },			  
              "target": "{{ nodeurl }}/iiif/canvas/p1" 
            } 
          ] 
       }
  ],
  "structures": [ 
    { 
      "id": "{{ nodeurl }}/iiif/range/r1", 
      "type": "Range", 
      "label": { 
        "{{ len }}": [ 
          {{ node.label|json_encode|raw  }} 
        ] 
      }, 
      "items": [ 
{% for rangeItem in structureCanvasIds %} 
        { 
          "id":  "{{ rangeItem }}", 
          "type": "Canvas" 
        }{{ not loop.last ? ',' : '' }} 
{% endfor %} 
      ] 
    } 
  ] 
}
] 
}
